function relocate_zone_blocked_build_geometry!(env)
    zone_keys = Symbol[p.first for p in active_restriction_zones()]
    isempty(zone_keys) && error("no active restriction zone is available for geometry relocation")

    result = translate_whole_build!(env; zone_keys = zone_keys)
    if !(result.status in (:translated, :already_clear))
        error("zone-compliant geometry relocation failed with status $(result.status)")
    end

    return (; status = :success)
end
